99	func heartbeatUsage() {
100		fmt.Println("usage: edgefleet heartbeat <submit|health|history> [flags]")
101		fmt.Println()
102		fmt.Println("commands:")
103		fmt.Println("  submit   receive heartbeats from stdin as a JSON array")
104		fmt.Println("  health   query node health from its latest telemetry")
105		fmt.Println("  history  list all heartbeats for a node, ascending by seq")
106		fmt.Println()
107		fmt.Println("input format (submit):")
108		fmt.Println("  A JSON array of heartbeat objects; every field is required.")
109		fmt.Println("    node          string   node id (non-empty, any length)")
110		fmt.Println("    seq           integer  sequence number (> 0)")
111		fmt.Println("    collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00")
112		fmt.Println("                           year 0000-9999; numeric offset hour 00-23 and")
113		fmt.Println("                           minute 00-59 on the minute (no seconds); +24:00")
114		fmt.Println("                           and out-of-range minutes like +00:60 are rejected,")
115		fmt.Println("                           not folded; must not be later than receive time;")
116		fmt.Println("                           a fractional second (with . or , as the decimal")
117		fmt.Println("                           separator) must be exact at nanosecond")
118		fmt.Println("                           precision: more than nine digits is accepted only")
119		fmt.Println("                           when every digit past the ninth is zero, never")
120		fmt.Println("                           truncated or rounded")
121		fmt.Println("    version       string   version (non-empty, valid Unicode text)")
122		fmt.Println("    height        integer  block height (>= 0)")
123		fmt.Println("    missed        integer  cumulative missed duties (>= 0)")
124		fmt.Println()
125		fmt.Println("  example:")
126		fmt.Println(`    [{"node":"val-eu-1","seq":7,"collected_at":"2026-10-01T11:59:00+08:00",`)
127		fmt.Println(`      "version":"1.26.0","height":12345,"missed":0}]`)
128		fmt.Println()
129		fmt.Println("flags:")
130		fmt.Println("  submit   --data-dir DIR        data directory (default: $EDGEFLEET_DATA_DIR or ~/.edgefleet)")
131		fmt.Println("           --receive-time TIME   receive time, RFC3339 (default: now)")
132		fmt.Println("  health   --node ID             node id (required)")
133		fmt.Println("           --expected-version V  expected version (required)")
134		fmt.Println("           --tolerated-misses N  tolerated missed duties, >= 0 (required)")
135		fmt.Println("           --missed-since-seq S  seq of a saved heartbeat used as the")
136		fmt.Println("                                missed-duty baseline (optional, > 0)")
137		fmt.Println("           --at TIME             query time, RFC3339 (default: now)")
138		fmt.Println("           --data-dir DIR        data directory")
139		fmt.Println()
140		fmt.Println("  Without --missed-since-seq the missed-duty alarm uses the cumulative")
141		fmt.Println("  missed count of the latest heartbeat (missed in the output). With it,")
142		fmt.Println("  the alarm counts only missed duties newly recorded between the baseline")
143		fmt.Println("  heartbeat seq S and the latest one; a count strictly greater than")
144		fmt.Println("  --tolerated-misses alarms, equality does not. The output then shows the")
145		fmt.Println("  baseline seq, the baseline cumulative count and the new count. If the")
146		fmt.Println("  cumulative counter decreased between the baseline and the latest record")
147		fmt.Println("  (e.g. after a node reset), the new count is shown as 无法判断 and a")
148		fmt.Println("  累计漏签数回退 finding is reported; the baseline must name an existing")
149		fmt.Println("  saved seq, otherwise the command fails.")
150		fmt.Println()
151		fmt.Println("  In health output, a node id or version containing whitespace, quotes,")
152		fmt.Println("  backslashes or control characters is shown as a quoted JSON string")
153		fmt.Println("  (newlines as \\n, tabs as \\t, other control characters as \\uXXXX),")
154		fmt.Println("  so every result stays on its own line; the stored text is unchanged.")
155		fmt.Println()
156		fmt.Println("  history  --node ID             node id (required)")
157		fmt.Println("           --data-dir DIR        data directory")
158		fmt.Println()
159		fmt.Println("data storage:")
160		fmt.Println("  One file per node under <data-dir>:")
161		fmt.Println("    nodes/<hex-node-id>.json for short node ids")
162		fmt.Println("    slots/<sha256-node-id>.json for ids too long for a file name")
163		fmt.Println("  A node id of any length is stored and queried by its full text;")
164		fmt.Println("  long ids are never rejected, truncated or renamed.")
165		fmt.Println("  Writes are atomic and the directory is locked for concurrent access.")
166		fmt.Println("  Corrupt data is refused, never silently cleared.")
167	}
