169	func newFlagSet(name string) *flag.FlagSet {
170		fs := flag.NewFlagSet(name, flag.ContinueOnError)
171		fs.SetOutput(os.Stderr)
172		fs.Usage = func() { heartbeatUsage() }
173		return fs
174	}
175	
176	func cmdSubmit(args []string) {
177		fs := newFlagSet("heartbeat submit")
178		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
179		receiveStr := fs.String("receive-time", "", "receive time (RFC3339); default: now")
180		if err := fs.Parse(args); err != nil {
181			if err == flag.ErrHelp {
182				os.Exit(0)
183			}
184			os.Exit(2)
185		}
186		if fs.NArg() != 0 {
187			die("submit takes no positional arguments; heartbeats are read from stdin")
188		}
189	
190		receiveTime := parseTimeFlag(*receiveStr, "--receive-time")
191	
192		data, err := io.ReadAll(os.Stdin)
193		if err != nil {
194			die("cannot read stdin: %v", err)
195		}
196		records, err := edgefleet.ParseHeartbeats(data, receiveTime)
197		if err != nil {
198			die("invalid input: %v", err)
199		}
200	
201		store, err := edgefleet.OpenStore(*dataDir)
202		if err != nil {
203			die("%v", err)
204		}
205		newCount, dupCount, err := store.Submit(records, receiveTime)
206		if err != nil {
207			die("%v", err)
208		}
209		fmt.Printf("submitted: new=%d duplicate=%d\n", newCount, dupCount)
210	}
211	
212	func cmdHealth(args []string) {
213		fs := newFlagSet("heartbeat health")
214		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
215		node := fs.String("node", "", "node id (required)")
216		atStr := fs.String("at", "", "query time (RFC3339); default: now")
217		expectedVersion := fs.String("expected-version", "", "expected version (required)")
218		toleratedMisses := fs.Int("tolerated-misses", -1, "tolerated missed duties, >= 0 (required)")
219		missedSinceSeq := fs.Int64("missed-since-seq", 0, "seq of a saved heartbeat to use as the missed-duty baseline; must be > 0 and exist for the node")
220		if err := fs.Parse(args); err != nil {
221			if err == flag.ErrHelp {
222				os.Exit(0)
223			}
224			os.Exit(2)
225		}
226		if *node == "" {
227			die("--node is required")
228		}
229		if *expectedVersion == "" {
230			die("--expected-version is required")
231		}
232		if *toleratedMisses < 0 {
233			die("--tolerated-misses is required and must be >= 0")
234		}
235		if isFlagPassed(fs, "missed-since-seq") && *missedSinceSeq <= 0 {
236			die("--missed-since-seq must be a positive integer")
237		}
238	
239		at := parseTimeFlag(*atStr, "--at")
240	
241		store, err := edgefleet.OpenStore(*dataDir)
242		if err != nil {
243			die("%v", err)
244		}
245	
246		var result edgefleet.HealthResult
247		if isFlagPassed(fs, "missed-since-seq") {
248			result, err = store.HealthSince(*node, at, *expectedVersion, *toleratedMisses, *missedSinceSeq)
249		} else {
250			result, err = store.Health(*node, at, *expectedVersion, *toleratedMisses)
251		}
252		if err != nil {
253			die("%v", err)
254		}
255	
256		// Node id and version go through the shared display rule: text that would
257		// break the one-line format (newlines, tabs, quotes, backslashes, control
258		// characters) is shown as a quoted JSON string, so a health query always
259		// prints exactly one line — two with a missed-duty baseline — and node
260		// text can never masquerade as extra fields or a second result line.
261		if result.Status == "notelemetry" {
262			fmt.Printf("node=%s status=无遥测 findings=[无遥测]\n", edgefleet.DisplayText(result.NodeID))
263			return
264		}
265		fmt.Printf("node=%s status=%s seq=%d collected_at=%s version=%s height=%d missed=%d findings=%v\n",
266			edgefleet.DisplayText(result.NodeID), result.Status, result.Seq, result.CollectedAt.Format(time.RFC3339),
267			edgefleet.DisplayText(result.Version), result.Height, result.Missed, result.Findings)
268		if isFlagPassed(fs, "missed-since-seq") {
269			// missed above stays cumulative; this line states the alarm basis.
270			if result.NewMissedKnown {
271				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=%d tolerated_misses=%d\n",
272					result.BaselineSeq, result.BaselineMissed, result.NewMissed, *toleratedMisses)
273			} else {
274				fmt.Printf("baseline_seq=%d baseline_missed=%d new_missed=无法判断 tolerated_misses=%d\n",
275					result.BaselineSeq, result.BaselineMissed, *toleratedMisses)
276			}
277		}
278	}
279	
280	// isFlagPassed reports whether the named flag was explicitly set on the
281	// command line, so an optional flag with a zero default can be distinguished
282	// from its absence.
283	func isFlagPassed(fs *flag.FlagSet, name string) bool {
284		passed := false
285		fs.Visit(func(f *flag.Flag) {
286			if f.Name == name {
287				passed = true
288			}
289		})
290		return passed
291	}
292	
293	func cmdHistory(args []string) {
294		fs := newFlagSet("heartbeat history")
295		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
296		node := fs.String("node", "", "node id (required)")
297		if err := fs.Parse(args); err != nil {
298			if err == flag.ErrHelp {
299				os.Exit(0)
300			}
301			os.Exit(2)
302		}
303		if *node == "" {
304			die("--node is required")
305		}
306	
307		store, err := edgefleet.OpenStore(*dataDir)
308		if err != nil {
309			die("%v", err)
310		}
311		records, err := store.History(*node)
312		if err != nil {
313			die("%v", err)
314		}
315		if len(records) == 0 {
316			fmt.Printf("node=%s no heartbeats\n", *node)
317			return
318		}
319		for _, r := range records {
320			fmt.Printf("node=%s seq=%d collected_at=%s version=%s height=%d missed=%d\n",
321				r.NodeID, r.Seq, r.CollectedAt.Format(time.RFC3339), r.Version, r.Height, r.Missed)
322		}
323	}
324	
325	func runDemo() {
326		nodes := []edgefleet.Node{
327			{ID: "val-eu-1", Region: "eu", Version: "1.26.0", Online: true},
328			{ID: "val-us-1", Region: "us", Version: "1.25.4", Online: true, Missed: 3},
329			{ID: "edge-ap-1", Region: "ap", Version: "1.26.0", Online: false},
330		}
331		unhealthy := 0
332		for _, node := range nodes {
333			health := edgefleet.Evaluate(node, "1.26.0", 1)
334			if !health.Healthy {
335				unhealthy++
336			}
337			fmt.Printf("node=%s healthy=%v findings=%v\n", health.Node, health.Healthy, health.Findings)
338		}
339		fmt.Println("rollout order:", edgefleet.Plan(nodes, "1.26.0"))
340		fmt.Printf("summary: %d of %d nodes need attention\n", unhealthy, len(nodes))
341	}
