12	// Heartbeat is one telemetry record reported by a node.
13	//
14	// JSON input uses snake_case field names:
15	//
16	//	node          string   node id (required, non-empty)
17	//	seq           integer  sequence number (required, > 0)
18	//	collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00
19	//	                      (required; year 0000-9999, numeric offset hour 00-23
20	//	                      and minute 00-59 on the minute — +24:00 and a folded
21	//	                      offset such as +00:60 are rejected, not normalised;
22	//	                      a fractional second, written with either "." or ","
23	//	                      as its decimal separator, must be exactly
24	//	                      representable at nanosecond precision — more than
25	//	                      nine digits is accepted only when every digit past
26	//	                      the ninth is zero, never truncated or rounded)
27	//	version       string   version (required, non-empty, valid Unicode text)
28	//	height        integer  block height (required, >= 0)
29	//	missed        integer  cumulative missed duties (required, >= 0)
30	type Heartbeat struct {
31		NodeID      string    `json:"node"`
32		Seq         int64     `json:"seq"`
33		CollectedAt time.Time `json:"collected_at"`
34		Version     string    `json:"version"`
35		Height      int64     `json:"height"`
36		Missed      int64     `json:"missed"`
37	}
38	
39	// heartbeatFields enumerates every field that must be explicitly provided.
40	var heartbeatFields = []string{"node", "seq", "collected_at", "version", "height", "missed"}
41	
42	// fieldIssue classifies the way a field value violates a rule. Together with
43	// the field name and the offending numeric value it identifies the rule that
44	// failed, without carrying any wording. Each trust boundary renders the
45	// failure in its own message style and locates it in its own context, but the
46	// rules themselves — which values are legal — live in the check* functions
47	// below exactly once.
48	type fieldIssue int
49	
50	const (
51		issueEmpty            fieldIssue = iota // a required string is ""
52		issueInvalidUnicode                     // node id or version is not lossless text
53		issueNotPositive                        // integer must be > 0
54		issueNegative                           // integer must be >= 0
55		issueMissingInstant                     // collected_at is the zero instant
56		issueYearOutOfRange                     // collected_at year cannot be written by the saved format
57		issueOffsetOutOfRange                   // collected_at timezone offset is not a whole minute within ±23:59
58	)
59	
60	// fieldValueError names the field whose value rule was violated.
61	type fieldValueError struct {
62		field string
63		issue fieldIssue
64		value int64
65	}
66	
67	// checkNodeIDValue holds the single node-id value rule: non-empty, valid
68	// Unicode text. The raw-JSON boundary additionally checks the un-decoded
69	// token (see validateRawText); for a value already decoded from such a
70	// token the Unicode branch can never fire, but both submit entries and the
71	// stored-data read enforce the same rule through this one function.
72	func checkNodeIDValue(node string) *fieldValueError {
73		if node == "" {
74			return &fieldValueError{field: "node", issue: issueEmpty}
75		}
76		if !utf8.ValidString(node) {
77			return &fieldValueError{field: "node", issue: issueInvalidUnicode}
78		}
79		return nil
80	}
81	
82	// checkVersionValue holds the single version value rule: non-empty, valid
83	// Unicode text. The version is opaque text — Chinese, emoji and a literal "�"
84	// the user typed are all legal, and no format (digits and dots) is imposed —
85	// but it must be losslessly representable: a platform that silently rewrites
86	// invalid bytes to U+FFFD would merge distinct versions into one and make the
87	// version-skew judgement compare text the node never reported. The raw-JSON
88	// boundary additionally checks the un-decoded token (see validateRawText);
89	// for a value already decoded from such a token the Unicode branch can never
90	// fire, but both submit entries and the stored-data read enforce the same
91	// rule through this one function.
92	func checkVersionValue(version string) *fieldValueError {
93		if version == "" {
94			return &fieldValueError{field: "version", issue: issueEmpty}
95		}
96		if !utf8.ValidString(version) {
97			return &fieldValueError{field: "version", issue: issueInvalidUnicode}
98		}
99		return nil
100	}
101	
102	// checkPositiveInt holds the single positive-integer rule (seq).
103	func checkPositiveInt(field string, value int64) *fieldValueError {
104		if value <= 0 {
105			return &fieldValueError{field: field, issue: issueNotPositive, value: value}
106		}
107		return nil
108	}
109	
110	// checkNonNegativeInt holds the single non-negative-integer rule (height,
111	// missed). An explicit zero is genuine telemetry and passes.
112	func checkNonNegativeInt(field string, value int64) *fieldValueError {
113		if value < 0 {
114			return &fieldValueError{field: field, issue: issueNegative, value: value}
115		}
116		return nil
117	}
118	
119	// checkCollectedAtValue holds the context-free collected_at rules shared by
120	// every boundary:
121	//
122	//   - the instant must actually be present (not the zero time);
123	//   - its year must be 0000..9999, the four-digit range the saved RFC3339
124	//     form can write — a year outside it cannot be persisted at all;
125	//   - its UTC offset must be a whole number of minutes no larger than
126	//     ±23:59, the offsets the saved form can write exactly. A ±24:00 offset
127	//     is outside the 00..23 hour bound, and a sub-minute offset (e.g.
128	//     +08:00:30) would silently land on disk as a different instant.
129	//
130	// Checking the decoded instant covers a Heartbeat built directly in Go;
131	// values decoded from JSON text additionally pass validateCollectedAtText,
132	// because time.Parse folds an out-of-range textual offset (+00:60 -> +01:00)
133	// before an instant ever exists to inspect.
134	func checkCollectedAtValue(collected time.Time) *fieldValueError {
135		if collected.IsZero() {
136			return &fieldValueError{field: "collected_at", issue: issueMissingInstant}
137		}
138		if year := collected.Year(); year < minSavedYear || year > maxSavedYear {
139			return &fieldValueError{field: "collected_at", issue: issueYearOutOfRange, value: int64(year)}
140		}
141		if _, offset := collected.Zone(); !isWritableOffset(offset) {
142			return &fieldValueError{field: "collected_at", issue: issueOffsetOutOfRange, value: int64(offset)}
143		}
144		return nil
145	}
146	
147	// Year bounds of the four-digit RFC3339 year the saved format writes.
148	const (
149		minSavedYear = 0
150		maxSavedYear = 9999
151	)
152	
153	// maxWritableOffsetSeconds is 23:59, the largest magnitude UTC offset whose
154	// hour and minute fields both fit the RFC3339 numeric offset (hour 00..23,
155	// minute 00..59). 24:00 is out of range, not an alias for the next day.
156	const maxWritableOffsetSeconds = 23*3600 + 59*60
157	
158	// isWritableOffset reports whether a UTC offset in seconds can be written by
159	// the on-disk RFC3339 form without losing or folding anything: it must be a
160	// whole number of minutes (a sub-minute offset has no representation), and
161	// its magnitude must be no greater than ±23:59.
162	func isWritableOffset(offsetSeconds int) bool {
163		if offsetSeconds%60 != 0 {
164			return false
165		}
166		if offsetSeconds < 0 {
167			offsetSeconds = -offsetSeconds
168		}
169		return offsetSeconds <= maxWritableOffsetSeconds
170	}
171	
172	// formatOffsetSeconds renders a UTC offset in seconds the way it was
173	// declared: ±HH:MM for a whole-minute offset, ±HH:MM:SS when a sub-minute
174	// part is present, so an error can show the exact offset that could not be
175	// saved (e.g. +08:00:45 or -24:00).
176	func formatOffsetSeconds(seconds int) string {
177		sign := "+"
178		if seconds < 0 {
179			sign = "-"
180			seconds = -seconds
181		}
182		hour := seconds / 3600
183		minute := (seconds % 3600) / 60
184		if rem := seconds % 60; rem != 0 {
185			return fmt.Sprintf("%s%02d:%02d:%02d", sign, hour, minute, rem)
186		}
187		return fmt.Sprintf("%s%02d:%02d", sign, hour, minute)
188	}
189	
190	// validateCollectedAtText guards the one gap in time.Parse(RFC3339) that the
191	// instant-level check cannot see: the standard library folds an out-of-range
192	// numeric timezone offset instead of rejecting it — "+00:60" parses as
193	// +01:00 and "+23:60" as +24:00 — and it accepts "+24:00"/"-24:00" even
194	// though the RFC3339 write layout cannot express them. The string has
195	// already passed time.Parse, so its shape is RFC3339 with a "Z" suffix or a
196	// six-character ±HH:MM suffix; here the offset's own hour and minute fields
197	// are required to be 00..23 and 00..59 with no carry-over between them.
198	func validateCollectedAtText(s string) error {
199		// "Z" is the only sign-less offset form; it denotes the zero offset.
200		if strings.HasSuffix(s, "Z") {
201			return nil
202		}
203		if len(s) < 6 {
204			return fmt.Errorf("timezone offset must be Z or ±HH:MM in %q", s)
205		}
206		off := s[len(s)-6:]
207		if (off[0] != '+' && off[0] != '-') || off[3] != ':' {
208			return fmt.Errorf("timezone offset must be Z or ±HH:MM, got %q", s)
209		}
210		hour, ok1 := twoDecimalDigits(off[1:3])
211		minute, ok2 := twoDecimalDigits(off[4:6])
212		if !ok1 || !ok2 {
213			return fmt.Errorf("timezone offset must be Z or ±HH:MM, got %q", s)
214		}
215		if hour > 23 {
216			return fmt.Errorf("timezone offset %s has hour %02d, must be 00-23", off, hour)
217		}
218		if minute > 59 {
219			return fmt.Errorf("timezone offset %s has minute %02d, must be 00-59 (out-of-range minutes are not folded into the hour)", off, minute)
220		}
221		return nil
222	}
223	
224	// twoDecimalDigits parses exactly two ASCII decimal digits.
225	func twoDecimalDigits(s string) (int, bool) {
226		if len(s) != 2 || s[0] < '0' || s[0] > '9' || s[1] < '0' || s[1] > '9' {
227			return 0, false
228		}
229		return int(s[0]-'0')*10 + int(s[1]-'0'), true
230	}
231	
232	// validateCollectedAtFraction guards the second gap in time.Parse(RFC3339)
233	// that the instant-level check cannot see: the standard library silently
234	// truncates a fractional second beyond nine digits — with either of the
235	// decimal separators it accepts, "." and "," — so ".1234567891" and
236	// ".1234567892", and likewise ",1234567891" and ",1234567892", both decode
237	// to the same nanosecond instant even though the node reported two different
238	// moments. Heartbeat collection times must be preserved exactly, so such
239	// input is refused under the same rule no matter which separator was written,
240	// never truncated or rounded. A fraction of at most nine digits always parses
241	// exactly, and a longer fraction is accepted only when every digit past the
242	// ninth is zero — the text then denotes the same instant as its nine-digit
243	// prefix (".1234567890" and ",123456789000" are both ".123456789"). The
244	// string has already passed time.Parse, so the "." or "," found here can only
245	// introduce the fractional second and what follows it up to the zone suffix
246	// is all digits.
247	func validateCollectedAtFraction(s string) error {
248		sep := strings.IndexAny(s, ".,")
249		if sep < 0 {
250			return nil
251		}
252		end := sep + 1
253		for end < len(s) && s[end] >= '0' && s[end] <= '9' {
254			end++
255		}
256		frac := s[sep:end] // separator plus digits, quoted verbatim in errors
257		digits := frac[1:]
258		if len(digits) <= 9 {
259			return nil
260		}
261		for i := 9; i < len(digits); i++ {
262			if digits[i] != '0' {
263				return fmt.Errorf("fractional second %s cannot be represented exactly at nanosecond precision: digit %d is not zero, and digits past the ninth must all be zero (the instant is never truncated or rounded)", frac, i+1)
264			}
265		}
266		return nil
267	}
268	
269	// checkHeartbeatValues runs every context-free field-value rule in the single
270	// rejection order shared by the direct-submit and stored-data boundaries:
271	// node, seq, version, height, missed, then collected_at. It deliberately does
272	// NOT compare against a receive time: reading saved history has no receive
273	// time, and that submit-only rule lives in checkCollectedAtTiming.
274	func checkHeartbeatValues(h Heartbeat) *fieldValueError {
275		if e := checkNodeIDValue(h.NodeID); e != nil {
276			return e
277		}
278		if e := checkPositiveInt("seq", h.Seq); e != nil {
279			return e
280		}
281		if e := checkVersionValue(h.Version); e != nil {
282			return e
283		}
284		if e := checkNonNegativeInt("height", h.Height); e != nil {
285			return e
286		}
287		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
288			return e
289		}
290		return checkCollectedAtValue(h.CollectedAt)
291	}
292	
293	// checkCollectedAtTiming holds the single receive-time rule, which belongs to
294	// submission only: a collection time later than the receive time is refused;
295	// the same instant expressed in another timezone is equal and allowed. The
296	// stored-data read path never calls this, so reading history introduces no
297	// current time and no extra time limit.
298	func checkCollectedAtTiming(collected, receiveTime time.Time) error {
299		if collected.After(receiveTime) {
300			return fmt.Errorf("collected_at %s is later than receive time %s",
301				collected.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
302		}
303		return nil
304	}
305	
306	// directError renders a field rule failure in ValidateHeartbeat's wording,
307	// used when a caller submits an already constructed Heartbeat.
308	func (e *fieldValueError) directError() error {
309		switch {
310		case e.field == "node" && e.issue == issueEmpty:
311			return fmt.Errorf("node id is empty")
312		case e.field == "node" && e.issue == issueInvalidUnicode:
313			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
314		case e.field == "seq":
315			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
316		case e.field == "version" && e.issue == issueInvalidUnicode:
317			return fmt.Errorf("version is not valid Unicode text: contains invalid UTF-8")
318		case e.field == "version":
319			return fmt.Errorf("version is empty")
320		case e.field == "height":
321			return fmt.Errorf("height must be >= 0, got %d", e.value)
322		case e.field == "missed":
323			return fmt.Errorf("missed must be >= 0, got %d", e.value)
324		case e.field == "collected_at":
325			switch e.issue {
326			case issueMissingInstant:
327				return fmt.Errorf("collected_at is missing or invalid")
328			case issueYearOutOfRange:
329				return fmt.Errorf("collected_at year %d cannot be saved: year must be 0000-9999", e.value)
330			case issueOffsetOutOfRange:
331				return fmt.Errorf("collected_at timezone offset %s cannot be saved exactly: offset must be a whole minute within -23:59 to +23:59", formatOffsetSeconds(int(e.value)))
332			}
333			return fmt.Errorf("collected_at is missing or invalid")
334		default:
335			return fmt.Errorf("field %q has an invalid value", e.field)
336		}
337	}
338	
339	// decodeError renders a field rule failure in the wording used while decoding
340	// a strict JSON object (submit input and stored records alike).
341	func (e *fieldValueError) decodeError() error {
342		switch {
343		case e.field == "node" && e.issue == issueInvalidUnicode:
344			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
345		case e.field == "node":
346			return fmt.Errorf("node must not be empty")
347		case e.field == "seq":
348			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
349		case e.field == "version" && e.issue == issueInvalidUnicode:
350			return fmt.Errorf("version is not valid Unicode text: contains invalid UTF-8")
351		case e.field == "version":
352			return fmt.Errorf("version must not be empty")
353		case e.field == "height":
354			return fmt.Errorf("height must be >= 0, got %d", e.value)
355		case e.field == "missed":
356			return fmt.Errorf("missed must be >= 0, got %d", e.value)
357		case e.field == "collected_at":
358			switch e.issue {
359			case issueMissingInstant:
360				return fmt.Errorf("collected_at is missing or invalid")
361			case issueYearOutOfRange:
362				return fmt.Errorf("collected_at year %d is out of range: year must be 0000-9999", e.value)
363			case issueOffsetOutOfRange:
364				return fmt.Errorf("collected_at timezone offset %s is out of range: offset must be a whole minute within -23:59 to +23:59", formatOffsetSeconds(int(e.value)))
365			}
366			return fmt.Errorf("collected_at is missing or invalid")
367		default:
368			return fmt.Errorf("invalid value for field %q", e.field)
369		}
370	}
371	
372	// storedError renders a field rule failure for a record read from a saved
373	// file, prefixing the 1-based record position as stored-data errors do.
374	func (e *fieldValueError) storedError(position int) error {
375		switch {
376		case (e.field == "node" || e.field == "version") && e.issue == issueInvalidUnicode:
377			return fmt.Errorf("record %d: field %q is not valid Unicode text", position, e.field)
378		case e.field == "node" || e.field == "version":
379			return fmt.Errorf("record %d: field %q must not be empty", position, e.field)
380		case e.field == "seq":
381			return fmt.Errorf("record %d: field %q must be a positive integer, got %d", position, e.field, e.value)
382		case e.field == "height" || e.field == "missed":
383			return fmt.Errorf("record %d: field %q must be >= 0, got %d", position, e.field, e.value)
384		case e.field == "collected_at":
385			switch e.issue {
386			case issueYearOutOfRange:
387				return fmt.Errorf("record %d: field %q year %d is out of range: year must be 0000-9999", position, e.field, e.value)
388			case issueOffsetOutOfRange:
389				return fmt.Errorf("record %d: field %q timezone offset %s is out of range: offset must be a whole minute within -23:59 to +23:59", position, e.field, formatOffsetSeconds(int(e.value)))
390			}
391			return fmt.Errorf("record %d: field %q is missing or invalid", position, e.field)
392		default:
393			return fmt.Errorf("record %d: field %q has an invalid value", position, e.field)
394		}
395	}
396	
397	// ValidateHeartbeat checks the semantic rules for one record. receiveTime is
398	// the moment the platform received the batch; a collection time later than
399	// receive time is rejected. The field-value rules are shared with JSON
400	// parsing and the stored-file read path via checkHeartbeatValues; only the
401	// receive-time comparison is submit-specific.
402	func ValidateHeartbeat(h Heartbeat, receiveTime time.Time) error {
403		if e := checkHeartbeatValues(h); e != nil {
404			return e.directError()
405		}
406		return checkCollectedAtTiming(h.CollectedAt, receiveTime)
407	}
408	
409	// Equal reports whether two records are the same telemetry. Collection times
410	// are compared as instants, so the same moment expressed in different
411	// timezones compares equal.
412	func (h Heartbeat) Equal(o Heartbeat) bool {
413		return h.NodeID == o.NodeID &&
414			h.Seq == o.Seq &&
415			h.Version == o.Version &&
416			h.Height == o.Height &&
417			h.Missed == o.Missed &&
418			h.CollectedAt.Equal(o.CollectedAt)
419	}
420	
421	// ParseHeartbeats parses a JSON array of heartbeat objects. Every field must
422	// be explicitly provided; missing or unknown fields are rejected with a
423	// specific reason.
424	func ParseHeartbeats(data []byte, receiveTime time.Time) ([]Heartbeat, error) {
425		var raw []json.RawMessage
426		if err := json.Unmarshal(data, &raw); err != nil {
427			return nil, fmt.Errorf("input must be a JSON array of heartbeat objects: %w", err)
428		}
429		if len(raw) == 0 {
430			return nil, fmt.Errorf("no heartbeat records provided")
431		}
432		records := make([]Heartbeat, 0, len(raw))
433		for i, r := range raw {
434			h, err := parseOneHeartbeat(r, receiveTime)
435			if err != nil {
436				return nil, fmt.Errorf("record %d: %w", i+1, err)
437			}
438			records = append(records, h)
439		}
440		return records, nil
441	}
442	
443	// rejectNull reports an error when a required field's JSON value is null.
444	// A null value means the node did not report the field, which must not be
445	// silently saved as the zero value.
446	func rejectNull(raw json.RawMessage, field string) error {
447		if bytes.Equal(raw, []byte("null")) {
448			return fmt.Errorf("%s must not be null", field)
449		}
450		return nil
451	}
452	
453	// objectFields collects the fields of one JSON object while enforcing the
454	// single field-uniqueness rule shared by every strict decoder in this
455	// package: within one object, a field name may appear only once. Names are
456	// compared as the JSON strings they decode to, so a plain spelling and a
457	// Unicode-escaped spelling of the same name collide, whether the repeated
458	// value is identical or different. The rule is scoped to the current object:
459	// the same field name appearing in another heartbeat object is unrelated.
460	// Both the submit-input decoder (decodeStrictHeartbeatObject) and the
461	// stored-file envelope decoder (decodeStrictNodeFile) apply the rule through
462	// this type; each boundary keeps its own error wording and its own check
463	// ordering for the rejection.
464	//
465	// A nil map value means the name has been seen but its value not decoded
466	// yet; once decoded, the value is stored under the name.
467	type objectFields map[string]json.RawMessage
468	
469	// check records one occurrence of a field name and reports whether the name
470	// already appeared in this object (duplicate == true).
471	func (o objectFields) check(name string) (duplicate bool) {
472		if _, exists := o[name]; exists {
473			return true
474		}
475		o[name] = nil
476		return false
477	}
478	
479	// has reports whether the field name appeared in this object.
480	func (o objectFields) has(name string) bool {
481		_, exists := o[name]
482		return exists
483	}
484	
485	// decodeStrictHeartbeatObject converts one JSON object's raw bytes into a
486	// Heartbeat while enforcing the field rules at every trust boundary: all
487	// fields must be present and non-null, unknown fields are rejected, and a
488	// field may never appear twice in the same object — even with the same
489	// value, and even when one spelling uses a JSON Unicode escape denoting the
490	// same key (the shared objectFields rule). A plain struct/map unmarshal
491	// would instead keep the last
492	// occurrence and let an absent field masquerade as the zero value. Both the
493	// submit input path and the stored-file read path must use it.
494	func decodeStrictHeartbeatObject(raw json.RawMessage) (Heartbeat, error) {
495		// Walk the object with a streaming decoder so duplicate field names are
496		// detected. Field names are compared as the JSON string they represent:
497		// "missed" and "m\u0069ssed" are the same field. A map-based unmarshal
498		// would silently keep only the last occurrence.
499		dec := json.NewDecoder(bytes.NewReader(raw))
500		tok, err := dec.Token()
501		if err != nil {
502			return Heartbeat{}, fmt.Errorf("record must be a JSON object: %w", err)
503		}
504		if d, ok := tok.(json.Delim); !ok || d != '{' {
505			return Heartbeat{}, fmt.Errorf("record must be a JSON object")
506		}
507	
508		fields := objectFields{}
509		for dec.More() {
510			keyTok, err := dec.Token()
511			if err != nil {
512				return Heartbeat{}, fmt.Errorf("invalid field: %w", err)
513			}
514			key, ok := keyTok.(string)
515			if !ok {
516				return Heartbeat{}, fmt.Errorf("field name must be a string")
517			}
518			if fields.check(key) {
519				return Heartbeat{}, fmt.Errorf("duplicate field %q", key)
520			}
521			var val json.RawMessage
522			if err := dec.Decode(&val); err != nil {
523				return Heartbeat{}, fmt.Errorf("invalid value for field %q: %w", key, err)
524			}
525			fields[key] = val
526		}
527		// Consume the closing brace.
528		if _, err := dec.Token(); err != nil {
529			return Heartbeat{}, fmt.Errorf("invalid record: %w", err)
530		}
531	
532		for _, f := range heartbeatFields {
533			if !fields.has(f) {
534				return Heartbeat{}, fmt.Errorf("missing required field %q", f)
535			}
536		}
537		for k := range fields {
538			if !containsString(heartbeatFields, k) {
539				return Heartbeat{}, fmt.Errorf("unknown field %q", k)
540			}
541		}
542	
543		var h Heartbeat
544	
545		if err := rejectNull(fields["node"], "node"); err != nil {
546			return Heartbeat{}, err
547		}
548		if err := json.Unmarshal(fields["node"], &h.NodeID); err != nil {
549			return Heartbeat{}, fmt.Errorf("node must be a string: %w", err)
550		}
551		if err := validateRawText(fields["node"], "node"); err != nil {
552			return Heartbeat{}, err
553		}
554		if e := checkNodeIDValue(h.NodeID); e != nil {
555			return Heartbeat{}, e.decodeError()
556		}
557	
558		if err := rejectNull(fields["seq"], "seq"); err != nil {
559			return Heartbeat{}, err
560		}
561		if err := json.Unmarshal(fields["seq"], &h.Seq); err != nil {
562			return Heartbeat{}, fmt.Errorf("seq must be an integer: %w", err)
563		}
564		if e := checkPositiveInt("seq", h.Seq); e != nil {
565			return Heartbeat{}, e.decodeError()
566		}
567	
568		if err := rejectNull(fields["collected_at"], "collected_at"); err != nil {
569			return Heartbeat{}, err
570		}
571		var collectedStr string
572		if err := json.Unmarshal(fields["collected_at"], &collectedStr); err != nil {
573			return Heartbeat{}, fmt.Errorf("collected_at must be a string: %w", err)
574		}
575		t, err := time.Parse(time.RFC3339, collectedStr)
576		if err != nil {
577			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
578		}
579		// time.Parse folds out-of-range numeric offsets (+00:60 -> +01:00) and
580		// accepts +24:00; verify the written offset before trusting the fold.
581		if err := validateCollectedAtText(collectedStr); err != nil {
582			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
583		}
584		// time.Parse also silently truncates a fractional second beyond nine
585		// digits for both accepted separators ("." and ","); the collection
586		// moment must be exactly representable.
587		if err := validateCollectedAtFraction(collectedStr); err != nil {
588			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
589		}
590		h.CollectedAt = t
591	
592		if err := rejectNull(fields["version"], "version"); err != nil {
593			return Heartbeat{}, err
594		}
595		if err := json.Unmarshal(fields["version"], &h.Version); err != nil {
596			return Heartbeat{}, fmt.Errorf("version must be a string: %w", err)
597		}
598		if err := validateRawText(fields["version"], "version"); err != nil {
599			return Heartbeat{}, err
600		}
601		if e := checkVersionValue(h.Version); e != nil {
602			return Heartbeat{}, e.decodeError()
603		}
604	
605		if err := rejectNull(fields["height"], "height"); err != nil {
606			return Heartbeat{}, err
607		}
608		if err := json.Unmarshal(fields["height"], &h.Height); err != nil {
609			return Heartbeat{}, fmt.Errorf("height must be an integer: %w", err)
610		}
611		if e := checkNonNegativeInt("height", h.Height); e != nil {
612			return Heartbeat{}, e.decodeError()
613		}
614	
615		if err := rejectNull(fields["missed"], "missed"); err != nil {
616			return Heartbeat{}, err
617		}
618		if err := json.Unmarshal(fields["missed"], &h.Missed); err != nil {
619			return Heartbeat{}, fmt.Errorf("missed must be an integer: %w", err)
620		}
621		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
622			return Heartbeat{}, e.decodeError()
623		}
624	
625		return h, nil
626	}
627	
628	// validateRawText checks the raw JSON string token of a text field (node or
629	// version) before its decoded value is trusted. encoding/json silently rewrites
630	// invalid UTF-8 bytes and unpaired \u surrogate escapes to U+FFFD, which
631	// would merge distinct texts into one replacement-char value: distinct node
632	// ids would collapse and break the ownership check against stored files, and
633	// distinct versions would collapse into text the node never reported,
634	// corrupting dedup and the version-skew judgement. The raw token must decode
635	// losslessly: every literal byte sequence must be valid UTF-8, and every \u
636	// escape must be a valid scalar value or a properly paired high/low
637	// surrogate pair. A literal "�" (or its \uFFFD escape) is valid text the
638	// user typed and is accepted; only undecodable input is rejected. A \\
639	// escape is consumed as a unit, so text that genuinely contains a backslash
640	// followed by "u" and hex digits is never re-interpreted as an escape.
641	func validateRawText(raw json.RawMessage, field string) error {
642		raw = bytes.TrimSpace(raw)
643		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
644			return fmt.Errorf("%s must be a string", field)
645		}
646		s := raw[1 : len(raw)-1]
647		for i := 0; i < len(s); {
648			c := s[i]
649			if c == '\\' {
650				if i+1 >= len(s) {
651					return fmt.Errorf("%s contains a truncated escape", field)
652				}
653				if s[i+1] != 'u' {
654					i += 2
655					continue
656				}
657				if i+6 > len(s) {
658					return fmt.Errorf("%s contains a truncated \\u escape", field)
659				}
660				r, err := parseHex4(s[i+2 : i+6])
661				if err != nil {
662					return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
663				}
664				switch {
665				case r >= 0xD800 && r <= 0xDBFF:
666					// A high surrogate is only valid when immediately followed
667					// by a low-surrogate \u escape.
668					if i+12 > len(s) || s[i+6] != '\\' || s[i+7] != 'u' {
669						return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
670					}
671					lo, err := parseHex4(s[i+8 : i+12])
672					if err != nil {
673						return fmt.Errorf("%s contains an invalid \\u escape: %w", field, err)
674					}
675					if lo < 0xDC00 || lo > 0xDFFF {
676						return fmt.Errorf("%s contains an unpaired high surrogate \\u%04X", field, r)
677					}
678					i += 12
679				case r >= 0xDC00 && r <= 0xDFFF:
680					return fmt.Errorf("%s contains an unpaired low surrogate \\u%04X", field, r)
681				default:
682					i += 6
683				}
684				continue
685			}
686			if c < utf8.RuneSelf {
687				i++
688				continue
689			}
690			// A valid multi-byte rune decodes with size >= 2; size 1 means the
691			// bytes are not valid UTF-8 (including surrogate encodings).
692			_, size := utf8.DecodeRune(s[i:])
693			if size == 1 {
694				return fmt.Errorf("%s contains invalid UTF-8 at byte offset %d", field, i)
695			}
696			i += size
697		}
698		return nil
699	}
700	
701	// parseHex4 parses exactly four hexadecimal digits as a 16-bit value.
702	func parseHex4(b []byte) (rune, error) {
703		v := 0
704		for _, c := range b {
705			var d int
706			switch {
707			case '0' <= c && c <= '9':
708				d = int(c - '0')
709			case 'a' <= c && c <= 'f':
710				d = int(c-'a') + 10
711			case 'A' <= c && c <= 'F':
712				d = int(c-'A') + 10
713			default:
714				return 0, fmt.Errorf("invalid hex digit %q", c)
715			}
716			v = v*16 + d
717		}
718		return rune(v), nil
719	}
720	
721	// parseOneHeartbeat decodes one submit-input record and applies the
722	// submit-only rule that collection time cannot be later than receive time.
723	func parseOneHeartbeat(raw json.RawMessage, receiveTime time.Time) (Heartbeat, error) {
724		h, err := decodeStrictHeartbeatObject(raw)
725		if err != nil {
726			return Heartbeat{}, err
727		}
728		if err := checkCollectedAtTiming(h.CollectedAt, receiveTime); err != nil {
729			return Heartbeat{}, err
730		}
731		return h, nil
732	}
733	
734	func containsString(list []string, s string) bool {
735		for _, v := range list {
736			if v == s {
737				return true
738			}
739		}
740		return false
741	}
