211	// lock acquires the directory lock. Exclusive for writes, shared for reads.
212	// The returned closure releases the lock.
213	func (s *Store) lock(exclusive bool) (func(), error) {
214		f, err := os.OpenFile(s.lockPath, os.O_RDWR|os.O_CREATE, 0o600)
215		if err != nil {
216			return nil, fmt.Errorf("cannot open lock file %s: %w", s.lockPath, err)
217		}
218		how := syscall.LOCK_SH
219		if exclusive {
220			how = syscall.LOCK_EX
221		}
222		if err := syscall.Flock(int(f.Fd()), how); err != nil {
223			f.Close()
224			return nil, fmt.Errorf("cannot acquire data lock: %w", err)
225		}
226		return func() {
227			syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
228			f.Close()
229		}, nil
230	}
