428	// writeNodeFile persists records atomically: a temp file in the same
429	// directory is fsynced and renamed over the target, so a crash never leaves
430	// a half-written file, and the containing directory is then opened and
431	// fsynced so the replacement itself is durable. A failure of that final
432	// directory confirmation (after the rename) is returned as *SaveConfirmError
433	// with the replaced file left intact.
434	//
435	// It is a package-level function variable rather than a plain func only so the
436	// persist stage can be deterministically failed from tests that exercise a
437	// real, mid-batch persistence failure (some node files already renamed into
438	// place before the failing one); production code always invokes the default
439	// implementation below and never reassigns it.
440	var writeNodeFile = func(path string, records []Heartbeat) error {
441		if records == nil {
442			records = []Heartbeat{}
443		}
444		nf := nodeFile{
445			Format:   formatMarker,
446			Checksum: checksumRecords(records),
447			Records:  records,
448		}
449		data, err := json.MarshalIndent(nf, "", "  ")
450		if err != nil {
451			return err
452		}
453		return writeFileAtomic(path, data)
454	}
455	
456	func writeFileAtomic(path string, data []byte) error {
457		dir := filepath.Dir(path)
458		tmp, err := os.CreateTemp(dir, ".tmp-*")
459		if err != nil {
460			return err
461		}
462		tmpName := tmp.Name()
463		if _, err := tmp.Write(data); err != nil {
464			tmp.Close()
465			os.Remove(tmpName)
466			return err
467		}
468		if err := tmp.Sync(); err != nil {
469			tmp.Close()
470			os.Remove(tmpName)
471			return err
472		}
473		if err := tmp.Close(); err != nil {
474			os.Remove(tmpName)
475			return err
476		}
477		if err := os.Rename(tmpName, path); err != nil {
478			os.Remove(tmpName)
479			return err
480		}
481		// The replacement is reachable but not yet confirmed durable: sync the
482		// containing directory. This is part of the save, and its failure is a save
483		// failure (see syncDirectoryDurably/SaveConfirmError); the renamed file is
484		// left intact either way.
485		return syncDirectoryDurably(dir)
486	}
487	
488	// syncDirectoryDurably opens dir and fsyncs it, confirming that a node file
489	// renamed into dir is durable. Both steps belong to the save stage: the
490	// directory may be unopenable (permissions, a dropped mount) or its fsync may
491	// return an I/O error, and either result means the replacement was not
492	// confirmed — although the rename already happened and the complete new file
493	// is reachable by name. Such a failure is therefore returned as
494	// *SaveConfirmError, never as corruption or a content error; the file on disk
495	// is well-formed and must not be rolled back.
496	//
497	// It is a package-level function variable for the same reason writeNodeFile
498	// is: the directory-sync step can be deterministically failed from tests that
499	// exercise a real, post-rename confirmation failure (the replacement already
500	// on disk when sync is refused). Production code always invokes the default
501	// implementation below and never reassigns it.
502	var syncDirectoryDurably = func(dir string) error {
503		d, err := os.Open(dir)
504		if err != nil {
505			return &SaveConfirmError{Dir: dir, Op: "open", Err: err}
506		}
507		syncErr := d.Sync()
508		d.Close()
509		if syncErr != nil {
510			return &SaveConfirmError{Dir: dir, Op: "sync", Err: syncErr}
511		}
512		return nil
513	}
514	
515	// mergeRecord applies the single dedup/conflict rule shared by both submit
516	// phases (records within the batch, and the batch against stored history): a
517	// record's identity is its node id and seq together, and known must contain
518	// only records of that same node. If known already holds the identity, the
519	// incoming record is a duplicate when Heartbeat.Equal says the content is
520	// identical — collection time compared as an instant, node id and version
521	// compared as-is — and a conflict when any field differs. A conflict is an
522	// error naming the node and seq and changes nothing; a duplicate leaves
523	// known untouched and reports dup. Otherwise the record is appended and
524	// returned in the updated slice.
525	func mergeRecord(known []Heartbeat, r Heartbeat) (updated []Heartbeat, dup bool, err error) {
526		for _, e := range known {
527			if e.Seq == r.Seq {
528				if !e.Equal(r) {
529					return nil, false, fmt.Errorf("conflicting record for node %q seq %d: content differs", r.NodeID, r.Seq)
530				}
531				return known, true, nil
532			}
533		}
534		return append(known, r), false, nil
535	}
536	
537	// Submit persists a batch of heartbeats. The whole batch is validated and
538	// checked for duplicates/conflicts against stored data (and within the batch)
539	// before anything is written: a single invalid or conflicting record fails
540	// the batch with no changes. Duplicates are counted, not written, and a node
541	// whose records are all duplicates of its saved history is not re-saved at
542	// all — only nodes that actually gained records are persisted. A
543	// successful return means the batch was durably persisted; a persistence
544	// failure is reported and previously queryable data is left intact.
545	func (s *Store) Submit(records []Heartbeat, receiveTime time.Time) (newCount, dupCount int, err error) {
546		if len(records) == 0 {
547			return 0, 0, fmt.Errorf("no heartbeat records provided")
548		}
549		for _, r := range records {
550			if err := ValidateHeartbeat(r, receiveTime); err != nil {
551				return 0, 0, fmt.Errorf("invalid heartbeat for node %q seq %d: %w", r.NodeID, r.Seq, err)
552			}
553		}
554	
555		unlock, err := s.lock(true)
556		if err != nil {
557			return 0, 0, err
558		}
559		defer unlock()
560	
561		// Deduplicate within the batch: same node+seq with equal content counts
562		// as a duplicate; same node+seq with differing content is a conflict.
563		merged := make(map[string][]Heartbeat)
564		for _, r := range records {
565			list, dup, err := mergeRecord(merged[r.NodeID], r)
566			if err != nil {
567				return 0, 0, err
568			}
569			if dup {
570				dupCount++
571				continue
572			}
573			merged[r.NodeID] = list
574		}
575	
576		// Merge with stored data per node, collecting new file contents. Every
577		// node's stored history is still loaded and checked (corruption or a
578		// conflict rejects the whole batch before anything is written), but a
579		// node whose records are all duplicates of what is already saved gains
580		// no record, so its file is left untouched: re-saving identical content
581		// would only turn a harmless retransmit into a write failure when the
582		// file's directory cannot be created or replaced.
583		type update struct {
584			loc     nodeLocation
585			records []Heartbeat
586		}
587		var updates []update
588		for nodeID, batch := range merged {
589			loc := s.nodeLocationFor(nodeID)
590			nf, err := loadNodeFile(loc)
591			if err != nil {
592				return 0, 0, err
593			}
594			existing := []Heartbeat{}
595			if nf != nil {
596				existing = nf.Records
597			}
598			nodeNew := 0
599			for _, r := range batch {
600				var dup bool
601				existing, dup, err = mergeRecord(existing, r)
602				if err != nil {
603					return 0, 0, err
604				}
605				if dup {
606					dupCount++
607				} else {
608					newCount++
609					nodeNew++
610				}
611			}
612			if nodeNew == 0 {
613				continue
614			}
615			sort.Slice(existing, func(i, j int) bool { return existing[i].Seq < existing[j].Seq })
616			updates = append(updates, update{loc: loc, records: existing})
617		}
618	
619		// Persist. All updates are appends to previously verified data, so a
620		// failure here leaves every previously queryable record intact. A failure
621		// can land after one node file's rename: the write itself completed but the
622		// directory durability confirmation (open/fsync) failed; that is still a
623		// save failure (SaveConfirmError) reported with zero counts, and the
624		// complete renamed file is left in place rather than rolled back.
625		for _, u := range updates {
626			if err := writeNodeFile(u.loc.path, u.records); err != nil {
627				return 0, 0, fmt.Errorf("failed to persist heartbeat batch: %w", err)
628			}
629		}
630		return newCount, dupCount, nil
631	}
