1	package main
2	
3	// Command-line regression tests for `edgefleet heartbeat health`.
4	//
5	// The domain rules (new-missed arithmetic, rollback detection, baseline
6	// validation) already have focused tests in package edgefleet. These tests
7	// protect what a user actually sees at the real command entry point:
8	//
9	//   - whether --missed-since-seq takes effect at all,
10	//   - the exact terminal output (cumulative missed stays on the first line,
11	//     baseline fields on the second),
12	//   - stdout vs stderr placement (health findings vs usage errors),
13	//   - and the process exit status (a health finding is not a command failure;
14	//     a bad baseline is).
15	//
16	// The tests re-execute the compiled test binary, which calls main() itself
17	// (see TestMain), so the code under test is the genuine command path — flag
18	// parsing included. Everything runs offline against a temp data directory
19	// with fixed receive/query instants, so no wall-clock waiting or network is
20	// involved.
21	
22	import (
23		"crypto/sha256"
24		"encoding/hex"
25		"errors"
26		"fmt"
27		"os"
28		"os/exec"
29		"path/filepath"
30		"strings"
31		"testing"
32	)
33	
34	const (
35		// cliTestEnv makes the re-executed test binary run the real main() instead
36		// of the test suite.
37		cliTestEnv = "EDGEFLEET_CLI_TEST_HELPER_PROCESS"
38	
39		// Fixed instants: heartbeats arrive and are queried at known times, so
40		// online status is deterministic without sleeping.
41		cliReceiveAt = "2026-10-01T12:00:00Z"
42		cliQueryAt   = "2026-10-01T12:00:00Z"
43	)
44	
45	// fixture holds a populated, isolated data directory.
46	type fixture struct {
47		t   *testing.T
48		dir string
49	}
50	
51	func TestMain(m *testing.M) {
52		if os.Getenv(cliTestEnv) == "1" {
53			// Run the genuine command entry point and let its own os.Exit calls
54			// determine the helper process status.
55			main()
56			os.Exit(0)
57		}
58		os.Exit(m.Run())
59	}
60	
61	// runCLI invokes the re-executed binary with the given arguments. stdin is
62	// fed to the command (used by `heartbeat submit`). It returns the captured
63	// stdout, stderr and exit code.
64	func runCLI(t *testing.T, dir, stdin string, args ...string) (string, string, int) {
65		t.Helper()
66		cmd := exec.Command(os.Args[0], args...)
67		cmd.Stdin = strings.NewReader(stdin)
68		// Keep HOME inside the temp area too, so a missing --data-dir could never
69		// touch the developer's real ~/.edgefleet.
70		cmd.Env = append(os.Environ(),
71			cliTestEnv+"=1",
72			"HOME="+dir,
73			"EDGEFLEET_DATA_DIR="+filepath.Join(dir, "env-data"),
74		)
75		var out, errOut strings.Builder
76		cmd.Stdout = &out
77		cmd.Stderr = &errOut
78		err := cmd.Run()
79		code := 0
80		if err != nil {
81			var exitErr *exec.ExitError
82			if errors.As(err, &exitErr) {
83				code = exitErr.ExitCode()
84			} else {
85				t.Fatalf("failed to run helper binary: %v", err)
86			}
87		}
88		return out.String(), errOut.String(), code
89	}
90	
91	// submitBatch stores one JSON array via the real submit command.
92	func submitBatch(t *testing.T, dir, json string) {
93		t.Helper()
94		out, errOut, code := runCLI(t, dir, json,
95			"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
96		if code != 0 {
97			t.Fatalf("submit exited %d: stderr=%q stdout=%q", code, errOut, out)
98		}
99	}
100	
101	// health runs the health command with the common fixed query time.
102	func health(t *testing.T, f *fixture, args ...string) (string, string, int) {
103		t.Helper()
104		full := append([]string{"heartbeat", "health", "--data-dir", f.dir, "--at", cliQueryAt}, args...)
105		return runCLI(t, f.dir, "", full...)
106	}
107	
108	// outputLines splits stdout into lines, treating a trailing newline as no
109	// extra empty line.
110	func outputLines(s string) []string {
111		s = strings.TrimRight(s, "\n")
112		if s == "" {
113			return nil
114		}
115		return strings.Split(s, "\n")
116	}
117	
118	// newFixture creates a temp data directory with three nodes:
119	//
120	//	mono:   seq 1/2/3, cumulative missed 12/13/14, version 1.26.0
121	//	reset:  seq 1/2/3, cumulative missed 12/5/14 (counter reset), version 1.25.0
122	//	gappy:  seq 1/3 (seq 2 never saved), missed 0/4, version 1.26.0
123	//
124	// Latest collection time is one second before cliQueryAt, so every node is
125	// online at the query instant.
126	func newFixture(t *testing.T) *fixture {
127		t.Helper()
128		f := &fixture{t: t, dir: t.TempDir()}
129	
130		submitBatch(t, f.dir, `[
131		  {"node":"mono","seq":1,"collected_at":"2026-10-01T11:59:57Z","version":"1.26.0","height":101,"missed":12},
132		  {"node":"mono","seq":2,"collected_at":"2026-10-01T11:59:58Z","version":"1.26.0","height":102,"missed":13},
133		  {"node":"mono","seq":3,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":103,"missed":14}
134		]`)
135		submitBatch(t, f.dir, `[
136		  {"node":"reset","seq":1,"collected_at":"2026-10-01T11:59:57Z","version":"1.25.0","height":201,"missed":12},
137		  {"node":"reset","seq":2,"collected_at":"2026-10-01T11:59:58Z","version":"1.25.0","height":202,"missed":5},
138		  {"node":"reset","seq":3,"collected_at":"2026-10-01T11:59:59Z","version":"1.25.0","height":203,"missed":14}
139		]`)
140		submitBatch(t, f.dir, `[
141		  {"node":"gappy","seq":1,"collected_at":"2026-10-01T11:59:57Z","version":"1.26.0","height":301,"missed":0},
142		  {"node":"gappy","seq":3,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":303,"missed":4}
143		]`)
144		return f
145	}
146	
147	func TestCLIHealthBaselineTakesEffect(t *testing.T) {
148		f := newFixture(t)
149	
150		// Baseline cumulative 12, latest cumulative 14, tolerance 2: the two new
151		// missed duties equal the tolerance and must NOT alarm.
152		out, errOut, code := health(t, f,
153			"--node", "mono", "--expected-version", "1.26.0",
154			"--tolerated-misses", "2", "--missed-since-seq", "1")
155		if code != 0 {
156			t.Fatalf("health query with a valid baseline must succeed, exit=%d stderr=%q", code, errOut)
157		}
158		if errOut != "" {
159			t.Errorf("health findings belong on stdout; stderr should be empty, got %q", errOut)
160		}
161	
162		lines := outputLines(out)
163		if len(lines) != 2 {
164			t.Fatalf("baseline query must print two lines, got %d: %q", len(lines), out)
165		}
166	
167		// The latest heartbeat (greatest seq) is still what the first line shows,
168		// and missed there stays the cumulative value (14), never the new count.
169		first := lines[0]
