375	// nodeFileHexPath mirrors the per-node file naming used by the store: short
376	// ids live under nodes/hex(id).json; ids too long for a file name live under
377	// slots/sha256(id).json.
378	func nodeFileHexPath(dir, node string) string {
379		hexName := hex.EncodeToString([]byte(node)) + ".json"
380		if len(hexName) <= 255 {
381			return filepath.Join(dir, "nodes", hexName)
382		}
383		sum := sha256.Sum256([]byte(node))
384		return filepath.Join(dir, "slots", hex.EncodeToString(sum[:])+".json")
385	}
386	
387	// corruptNodeFile overwrites one node's saved file with raw content.
388	func corruptNodeFile(t *testing.T, dir, node, content string) {
389		t.Helper()
390		if err := os.WriteFile(nodeFileHexPath(dir, node), []byte(content), 0o644); err != nil {
391			t.Fatal(err)
392		}
393	}
394	
395	// readNodeFile returns the current raw bytes of a node's file.
396	func readNodeFile(t *testing.T, dir, node string) string {
397		t.Helper()
398		b, err := os.ReadFile(nodeFileHexPath(dir, node))
399		if err != nil {
400			t.Fatal(err)
401		}
402		return string(b)
403	}
