645	// non-zero exit, no success counts on stdout, an error naming the record and
646	// the node field on stderr, and no change to any stored data.
647	func TestCLISubmitRejectsInvalidUTF8Node(t *testing.T) {
648		f := newFixture(t)
649		monoBefore := readNodeFile(t, f.dir, "mono")
650	
651		badRecord := `{"node":"val-` + "\xff" + `1","seq":1,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":1,"missed":0}`
652		goodRecord := `{"node":"mono","seq":4,"collected_at":"2026-10-01T11:59:59Z","version":"1.26.0","height":104,"missed":15}`
653		out, errOut, code := runCLI(t, f.dir, "["+goodRecord+","+badRecord+"]",
654			"heartbeat", "submit", "--data-dir", f.dir, "--receive-time", cliReceiveAt)
655		if code == 0 {
656			t.Errorf("submit with an invalid UTF-8 node id must exit non-zero; stdout=%q", out)
657		}
658		if strings.Contains(out, "submitted") {
659			t.Errorf("rejected batch must not print success counts, stdout=%q", out)
660		}
661		if !strings.Contains(errOut, "record 2") || !strings.Contains(errOut, "node") {
662			t.Errorf("stderr must name the failing record and the node field, got %q", errOut)
663		}
664	
665		// The valid record in the same batch is not saved either.
666		if got := readNodeFile(t, f.dir, "mono"); got != monoBefore {
667			t.Errorf("existing node file changed during rejected submit")
668		}
669		if _, err := os.Stat(nodeFileHexPath(f.dir, "val-�1")); !os.IsNotExist(err) {
670			t.Errorf("no node file may be created for the rewritten id, stat err=%v", err)
671		}
672	
673		// Health answers for the existing node are unchanged.
674		out, _, code = health(t, f,
675			"--node", "mono", "--expected-version", "1.26.0", "--tolerated-misses", "9")
676		if code != 0 || !strings.Contains(out, "seq=3") {
677			t.Errorf("health after rejected batch changed: code=%d out=%q", code, out)
678		}
679	}
