869	// TestCLISubmitContentDifferencesConflictAgainstHistory covers every field
870	// that makes a same-node/same-seq record a conflict rather than a duplicate:
871	// version, height, cumulative missed, and the collection instant (including
872	// equal wall-clock text with a different offset, which is a different
873	// instant). Nothing is overwritten and no last-write-wins occurs.
874	func TestCLISubmitContentDifferencesConflictAgainstHistory(t *testing.T) {
875		const base = `{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":0}`
876		cases := []struct {
877			name string
878			// incoming is the conflicting record, same node+seq as the saved one.
879			incoming string
880		}{
881			{"version differs",
882				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.27.0","height":100,"missed":0}`},
883			{"height differs",
884				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":101,"missed":0}`},
885			{"missed differs",
886				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00Z","version":"1.26.0","height":100,"missed":1}`},
887			{"collected instant differs",
888				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:58:00Z","version":"1.26.0","height":100,"missed":0}`},
889			{"same wall clock text, different offset is a different instant",
890				`{"node":"%s","seq":2,"collected_at":"2026-10-01T11:59:00+08:00","version":"1.26.0","height":100,"missed":0}`},
891		}
892		for _, tc := range cases {
893			t.Run(tc.name, func(t *testing.T) {
894				dir := t.TempDir()
895				// Each subtest gets its own data directory, so one fixed node id
896				// carrying the saved seq-2 baseline is enough.
897				const node = "node"
898				submitBatch(t, dir, "["+fmt.Sprintf(base, node)+"]")
899				before := historyLines(t, dir, node)
900	
901				out, errOut, code := submit(t, dir, "["+fmt.Sprintf(tc.incoming, node)+"]")
902				if code == 0 {
903					t.Fatalf("conflicting record must fail non-zero; stdout=%q", out)
904				}
905				// The error names the node and the seq, and goes to stderr.
906				for _, want := range []string{"error:", "conflict", node, "seq 2"} {
907					if !strings.Contains(errOut, want) {
908						t.Errorf("stderr %q must contain %q", errOut, want)
909					}
910				}
911				// No success line or counters on stdout.
912				if strings.Contains(out, "submitted") || strings.Contains(out, "new=") {
913					t.Errorf("rejected batch must not print success counts, stdout=%q", out)
914				}
915				// The original telemetry is intact: not replaced by the incoming
916				// content, not counted as a duplicate.
917				after := historyLines(t, dir, node)
918				if len(after) != 1 || after[0] != before[0] {
919					t.Errorf("history changed after conflict:\nbefore=%q\nafter =%q", before, after)
920				}
921			})
922		}
923	}
