925	// TestCLISubmitConflictWithinBatchRejectsEverything checks the first conflict
926	// condition: two records of the same node+seq with differing content inside
927	// one batch fail the whole batch. Legal records for other nodes — whether
928	// they appear before or after the conflicting pair — must not survive, and a
929	// pre-existing node touched by a legal record in the same batch stays as it
930	// was before the submit.
931	func TestCLISubmitConflictWithinBatchRejectsEverything(t *testing.T) {
932		dir := t.TempDir()
933		// Existing node 旧 with seq 1 already saved.
934		submitBatch(t, dir, `[
935		  {"node":"旧","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0","height":10,"missed":0}
936		]`)
937		oldBefore := readNodeFile(t, dir, "旧")
938	
939		// Batch layout: legal record for a brand-new node 新, then a legal seq-2
940		// for the existing node, then the in-batch conflict on 甲 seq 1, then
941		// another legal new-node record. None of the legal ones may be saved.
942		batch := `[
943		  {"node":"新","seq":1,"collected_at":"2026-10-01T11:59:10Z","version":"1.0","height":20,"missed":0},
944		  {"node":"旧","seq":2,"collected_at":"2026-10-01T11:59:20Z","version":"1.0","height":11,"missed":0},
945		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:30Z","version":"1.0","height":100,"missed":0},
946		  {"node":"甲","seq":1,"collected_at":"2026-10-01T11:59:30Z","version":"2.0","height":100,"missed":0},
947		  {"node":"丙","seq":1,"collected_at":"2026-10-01T11:59:40Z","version":"1.0","height":30,"missed":0}
948		]`
949		out, errOut, code := submit(t, dir, batch)
950		if code == 0 {
951			t.Fatalf("in-batch conflict must fail non-zero; stdout=%q", out)
952		}
953		for _, want := range []string{"error:", "conflict", "甲", "seq 1"} {
954			if !strings.Contains(errOut, want) {
955				t.Errorf("stderr %q must contain %q", errOut, want)
956			}
957		}
958		if strings.Contains(out, "submitted") || strings.Contains(out, "new=") {
959			t.Errorf("rejected batch must print no success counts, stdout=%q", out)
960		}
961	
962		// Existing node untouched even though its legal record came first.
963		if got := readNodeFile(t, dir, "旧"); got != oldBefore {
964			t.Errorf("existing node file was modified by the rejected batch")
965		}
966		// Brand-new nodes in the batch must have no history at all.
967		for _, node := range []string{"新", "甲", "丙"} {
968			out, errOut, code := historyCLI(t, dir, node)
969			if code != 0 {
970				t.Fatalf("history query after rejected batch must itself work for %q: %d %q", node, code, errOut)
971			}
972			if strings.TrimRight(out, "\n") != "node="+node+" no heartbeats" {
973				t.Errorf("node %q must have no records after rejected batch, got %q", node, out)
974			}
975			if _, err := os.Stat(nodeFileHexPath(dir, node)); !os.IsNotExist(err) {
976				t.Errorf("no file may be created for node %q, stat err=%v", node, err)
977			}
978		}
979	}
